import re

OPEN_DICT = re.compile(r"^(?P<indent>\s*)(?P<key>\S(?:.*?\S)?) \{\s*$")
OPEN_LIST = re.compile(r"^(?P<indent>\s*)(?P<key>\S(?:.*?\S)?) \[(?: \((?P<value>[^)]*)\))?\s*$")
CLOSE = re.compile(r"^\s*[\]}]\s*$")
KV = re.compile(r"^\s*(?P<key>[^:]+?):\s*(?P<value>.*?)\s*$")
ITEM = re.compile(r"^\s*(?P<name>\S+)(?: \((?P<value>[^)]*)\))?\s*$")


def read(lines, i, n):
    """Parse lines[i:] up to a closing bracket at depth 0; -> (entries, next i).
    An entry is (key, value, start line, end line) where value is a str,
    ("dict", entries) or ("list", value, entries)."""
    out = []
    while i < n:
        ln = lines[i]
        if not ln.strip():
            i += 1; continue
        if CLOSE.match(ln):
            return out, i + 1
        m = OPEN_DICT.match(ln)
        if m:
            kids, j = read(lines, i + 1, n)
            out.append((m.group("key"), ("dict", kids), i, j - 1)); i = j; continue
        m = OPEN_LIST.match(ln)
        if m:
            kids, j = read(lines, i + 1, n)
            out.append((m.group("key"), ("list", m.group("value") or "", kids), i, j - 1)); i = j; continue
        m = KV.match(ln)
        if m:
            out.append((m.group("key"), m.group("value"), i, i)); i += 1; continue
        m = ITEM.match(ln)
        if m:
            out.append(("", m.group("name"), i, i)); i += 1; continue
        out.append(("?", ln.strip(), i, i)); i += 1
    return out, i


def flatten(entries, prefix, rec, subs):
    for key, val, s, e in entries:
        name = prefix + key
        if isinstance(val, str):
            rec[name] = val
        elif val[0] == "dict":
            flatten(val[1], name + ".", rec, subs)
        else:
            items = [k for k in val[2] if isinstance(k[1], str)]
            dicts = [k for k in val[2] if not isinstance(k[1], str)]
            if val[1]:
                rec[name] = val[1]
                rec[name + ".set"] = ",".join(k[1] for k in items)
            elif not dicts:
                rec[name] = ",".join(k[1] for k in items)
            if dicts:
                subs.append((name, dicts))


def parse(lines):
    n = len(lines)
    entries, _ = read(lines, 0, n)
    skip, blocks = [], []
    top, top_lines = {}, []
    for key, val, s, e in entries:
        if isinstance(val, str):
            top[key] = val; top_lines.append(s)
            continue
        if val[0] == "dict":
            rec, subs = {}, []
            flatten(val[1], "", rec, subs)
            blocks.append({"name": key, "kind": "kv", "lines": list(range(s, e + 1)), "records": [rec]})
            continue
        skip += [s, e]
        recs, rec_lines, subs = [], [], []
        for k, v, ks, ke in val[2]:
            if isinstance(v, str):
                top[key] = (top.get(key, "") + "," + v).strip(","); top_lines.append(ks); continue
            rec, mysubs = {}, []
            flatten(v[1] if v[0] == "dict" else v[2], "", rec, mysubs)
            recs.append(rec); rec_lines += list(range(ks, ke + 1))
            for sname, dicts in mysubs:
                subs.append((sname, rec, dicts))
        keys = []
        for r in recs:
            for k in r:
                if k not in keys:
                    keys.append(k)
        recs = [{k: r.get(k, "") for k in keys} for r in recs]
        blocks.append({"name": key, "kind": "table", "lines": rec_lines, "records": recs})
        for sname, parent, dicts in subs:
            pk = next(iter(parent), "")
            srecs = []
            for k, v, ks, ke in dicts:
                rec, _ = {key + "." + pk: parent.get(pk, "")}, []
                flatten(v[1] if v[0] == "dict" else v[2], "", rec, _)
                srecs.append(rec)
            blocks.append({"name": key + "." + sname, "kind": "table", "lines": [], "records": srecs})
    if top:
        blocks.insert(0, {"name": "file", "kind": "kv", "lines": top_lines, "records": [top]})
    return {"blocks": blocks, "skip": skip}
